    {
      "rank": 1,
      "ballot_id": "B011",
      "proposed_laureates": [
        "John J. Croat",
        "Masato Sagawa"
      ],
      "assessment": {
        "nobel_worthiness": "The neodymium-iron-boron magnet is a decisive materials discovery, coupling fundamental understanding of rare-earth magnetism to an enormous technological transformation in motors, energy conversion, and information technology.",
        "attribution": "Sagawa and Croat represent the central independent development of the high-performance Nd-Fe-B permanent magnet.",
        "maturity": "Its exceptional magnetic performance, manufacturability, and long-term societal impact have been established beyond doubt over decades.",
        "uncertainties": [
          "The relative framing of the discovery versus subsequent materials optimization requires careful historical delineation."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electron materials quantitatively tractable and changed how theory connects electronic structure to observed spectra and phases.",
        "attribution": "Georges, Kotliar, and Vollhardt are the essential architects of the formulation and its establishment as a practical framework.",
        "maturity": "The method has been tested broadly against experiment and has become a durable foundation of correlated-materials research.",
        "uncertainties": [
          "A prize would need to distinguish the foundational theory clearly from the wide subsequent ecosystem of extensions and implementations."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "Topological insulators and the quantum spin Hall effect revealed a new robust phase of quantum matter, with a profound conceptual and experimental influence.",
        "attribution": "Kane and Mele supplied the defining quantum spin Hall theory, while Molenkamp provided a landmark experimental realization.",
        "maturity": "Topological boundary physics has been independently established across material platforms and is now a central part of condensed-matter physics.",
        "uncertainties": [
          "The appropriate boundary between early quantum spin Hall work, three-dimensional topological insulators, and later related effects remains attribution-sensitive."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Christian Pfleiderer",
        "Roland Wiesendanger",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetic skyrmions made topological spin textures an experimentally controllable form of matter with striking new dynamics and device potential.",
        "attribution": "Pfleiderer, Wiesendanger, and Tokura respectively represent key bulk, real-space imaging, and materials-and-control contributions.",
        "maturity": "The textures, their topology, and their characteristic response to currents have been reproduced extensively in distinct magnetic systems.",
        "uncertainties": [
          "The discovery spans several experimental routes and may be difficult to compress into a uniquely bounded three-person attribution."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B048",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Shinji Yuasa",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Giant tunnel magnetoresistance provided a powerful quantum spin-dependent tunnelling effect and a major basis for modern spintronic devices.",
        "attribution": "Moodera, Miyazaki, and Yuasa represent foundational demonstrations and the development of the effect into a high-performance materials platform.",
        "maturity": "The phenomenon is quantitatively well understood and validated through widespread technological implementation.",
        "uncertainties": [
          "Its relationship to the already recognized broader field of giant magnetoresistance would require especially precise prize wording."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene uncovered an unexpected route to correlated and topological electronic states through moiré engineering.",
        "attribution": "Bistritzer and MacDonald provided the decisive theoretical magic-angle framework, and Jarillo-Herrero led the transformative experimental observations.",
        "maturity": "The principal correlated phenomena and moiré-band mechanism have been reproduced and extended to a broad family of layered materials.",
        "uncertainties": [
          "The precise microscopic account of some ordered phases and superconductivity remains actively debated."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Franz J. Giessibl",
        "Gerhard Meyer",
        "Leo Gross"
      ],
      "assessment": {
        "nobel_worthiness": "Atomic-resolution qPlus force microscopy enabled direct, chemically informative imaging and manipulation of individual molecules and bonds.",
        "attribution": "Giessibl pioneered the qPlus approach, while Meyer and Gross made decisive advances in atomic-scale imaging and molecular structural identification.",
        "maturity": "The technique is highly reproducible, physically interpretable, and deeply influential in surface and molecular science.",
        "uncertainties": [
          "Its achievement may be judged as a major instrumentation advance rather than a sufficiently singular physical discovery."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Ioan Mihai Miron",
        "Pietro Gambardella",
        "Robert A. Buhrman"
      ],
      "assessment": {
        "nobel_worthiness": "Spin-orbit torques established an efficient means to manipulate magnetic order electrically, opening a distinctive route to low-energy spintronic functionality.",
        "attribution": "Miron, Gambardella, and Buhrman represent central experimental discoveries and demonstrations of the relevant torque mechanisms.",
        "maturity": "The effects are robustly reproduced across material classes and have motivated substantial device physics and industrial research.",
        "uncertainties": [
          "Several intertwined bulk and interfacial mechanisms make priority and the most fundamental attribution less clean than for the highest-ranked cases."
        ]
      }
    }
  ]
